export const getComponent = (slug: string) => components.find((c) => c.slug === slug)
export const stats = {
  components: components.length,
  categories: categories.length - 1,
  installMethods: 4,
}

export const installCommand = (slug: string, manager = 'pnpm') =>
  `${manager} dlx shadcn@latest add https://flourish-ui.dev/r/${slug}.json`

export const registryItem = (component: ComponentEntry) => ({
  $schema: 'https://ui.shadcn.com/schema/registry-item.json',
  name: component.slug,
  type: 'registry:ui',
  title: component.title,
  description: component.description,
  author: 'Zuhaib Rashid <zuhaibrashid01@gmail.com>',
  dependencies: component.dependencies,
  devDependencies: [],
  registryDependencies: [],
  files: [
    {
      path: `components/flourish/${component.slug}.tsx`,
      content: component.code,
      type: 'registry:ui',
    },
  ],
})
